import{z as n,x as o,o as B,c as m,q as r,j as t,D as e,d as a,s as i,S as s,b as A}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"数值对齐与基线校准","description":"","frontmatter":{"title":"数值对齐与基线校准","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rw-baseline-alignment.md","filePath":"llm/rw-baseline-alignment.md","lastUpdated":1791413859000}'),d={name:"llm/rw-baseline-alignment.md"};function p(D,E,c,h,C,u){const l=o("Mermaid");return B(),m("div",null,[E[2]||(E[2]=r('<h1 id="数值对齐与基线校准" tabindex="-1">数值对齐与基线校准 <a class="header-anchor" href="#数值对齐与基线校准" aria-label="Permalink to &quot;数值对齐与基线校准&quot;">​</a></h1><div class="epigraph"><p>在一个调平了的基线面前，大多数「突破」安静地退回到噪声里；这不是领域的不幸，是度量开始诚实。</p><footer>—— 据 Ferrari Dacrema 等, Are We Really Making Much Progress?, RecSys 2019 整理</footer></div><p><a href="/llm/rw-compute-budgeting">上一课</a>的阶梯走到了 full 级，该问两个收官问题：你的数字与论文「对上了」吗？你的方法「赢」了吗？两个词都必须先有定义才能回答。「对上」是复现的验收——数字落在约定的容差里；「赢」是对比的资格——基线在同等预算下调到自己的最好努力。本课写这两个定义如何落成可执行的检查。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>「对不上」是一个症状，不是判定；没有容差定义的对齐检查会永无止境：差 0.5 分时你不知道该继续归因还是宣布成功。更隐蔽的是基线资格问题：复现方法复现时，你的实现往往要和基线比——但基线是谁调的、调了多久、在什么预算下，决定了「赢」字有没有语义。两个失败模式相对：对齐容差没定，验收拖成持久战；基线没校准，赢来的结论被基线欠账一笔勾销。</p><p><span class="marginnote">「基线校准」就是先给对手做陪练：确认你复刻的基线能跑出官方成绩，再在你的环境里帮它把关键超参调到它的最好状态。对手被调到最强之后你还赢，这个「赢」才算数；赢一个没吃饱的对手不算。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对齐锚点从粗到细四层。第一层端到端指标：benchmark 分数，容差在声明（第一课）里定，通常给相对容差而不是绝对容差——小数点后第三位的绝对差在大基准上无意义。第二层曲线形态：loss 曲线的斜率、拐点位置、退火尾部的落差与<a href="/llm/ti-loss-curve-reading">loss 曲线的解读</a>的形态学对照。第三层中间统计：逐层激活均值与方差、梯度范数，口径见<a href="/llm/ti-numerical-health">数值健康检查</a>。第四层单步复算：走读一课定位的那「一步」，在完全相同的 batch 上与参考实现逐项对账——loss 与梯度分量的相对误差。先粗后细的次序是纪律：粗层没对齐时细层的差异不可解释（数据都不同，逐层统计本来就不同），先细后粗会误导归因。</p><p>基线校准三步：复刻官方基线配置，确认能跑出官方数字；在你的环境里为基线重调关键超参（学习率、权重衰减的小网格）；把「基线的最好努力」连同调参空间一起记档。校准费用在上一课的预算表里有一成份额，不是白送的善意，是对比的资格费。</p><p><span class="marginnote">数字实例：为什么写相对容差而不写绝对容差——同样是 0.1 分的容差，在 80 分的基准上只占 0.125%，在 20 分的小任务上却是 0.5%。基数不同，同样的绝对差含义完全不同，写相对比例才能跨任务复用同一条验收线。</span></p>',10)),(B(),t(s,null,{default:e(()=>[i(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20ALIGN%5B%22%E5%AF%B9%E9%BD%90%EF%BC%9A%E7%B2%97%E5%88%B0%E7%BB%86%22%5D%20--%3E%20A1%5B%22%E7%AB%AF%E5%88%B0%E7%AB%AF%E6%8C%87%E6%A0%87%E4%B8%8E%E5%AE%B9%E5%B7%AE%22%5D%0A%20%20A1%20--%3E%20A2%5B%22%E6%9B%B2%E7%BA%BF%E5%BD%A2%E6%80%81%22%5D%0A%20%20A2%20--%3E%20A3%5B%22%E9%80%90%E5%B1%82%E7%BB%9F%E8%AE%A1%22%5D%0A%20%20A3%20--%3E%20A4%5B%22%E5%8D%95%E6%AD%A5%E5%A4%8D%E7%AE%97%EF%BC%9A%E5%90%8C%20batch%20%E5%AF%B9%E8%B4%A6%22%5D%0A%20%20BASE%5B%22%E5%9F%BA%E7%BA%BF%E6%A0%A1%E5%87%86%22%5D%20--%3E%20B1%5B%22%E5%A4%8D%E5%88%BB%E5%AE%98%E6%96%B9%E9%85%8D%E7%BD%AE%22%5D%0A%20%20B1%20--%3E%20B2%5B%22%E7%8E%AF%E5%A2%83%E5%86%85%E9%87%8D%E8%B0%83%E8%B6%85%E5%8F%82%22%5D%0A%20%20B2%20--%3E%20B3%5B%22%E6%9C%80%E5%A5%BD%E5%8A%AA%E5%8A%9B%E8%AE%B0%E6%A1%A3%22%5D%0A%20%20A4%20--%3E%20VERDICT%5B%22%E9%AA%8C%E6%94%B6%E5%88%A4%E5%AE%9A%EF%BC%9A%E5%AF%B9%E4%B8%8A%2F%E6%9C%AA%E5%AF%B9%E4%B8%8A%22%5D%0A%20%20B3%20--%3E%20VERDICT%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[a("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,[a("为什么单步复算是最强锚点：它把训练动力学与规模全部冻结，差异只剩前向数值、反向数值与初始化——归因空间被压到最小。它也是最贵的锚点（要求参考实现可运行），所以放在最细层按需使用。为什么容差从坐标系来：相同数据加相同种子，期望接近逐位一致；相同数据不同实现，期望同分布（统计容差）；数据近似同源，只求排序一致。容差写错档位，对齐判定就失去含义——拿逐位标准去要求独立实现，永远「失败」；拿排序标准去验收数字线，永远「成功」。跨硬件的逐位一致不可得，那是"),A("a",{href:"/llm/num-crosshardware-consistency"},"跨硬件的数值一致性"),a("的专题，本课的容差默认在统计档。")],-1)),(B(),t(s,null,{default:e(()=>[i(l,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E4%BD%A0%E7%9A%84%E6%95%B0%E6%8D%AE%E4%B8%8E%E5%AE%9E%E7%8E%B0%E6%98%AF%E4%BB%80%E4%B9%88%E5%85%B3%E7%B3%BB%22%5D%20--%3E%20S1%5B%22%E5%90%8C%E6%95%B0%E6%8D%AE%E5%8A%A0%E5%90%8C%E7%A7%8D%E5%AD%90%22%5D%0A%20%20Q%20--%3E%20S2%5B%22%E5%90%8C%E6%95%B0%E6%8D%AE%E3%80%81%E4%B8%8D%E5%90%8C%E5%AE%9E%E7%8E%B0%22%5D%0A%20%20Q%20--%3E%20S3%5B%22%E6%95%B0%E6%8D%AE%E8%BF%91%E4%BC%BC%E5%90%8C%E6%BA%90%22%5D%0A%20%20S1%20--%3E%20T1%5B%22%E6%9C%9F%E6%9C%9B%E9%80%90%E4%BD%8D%E4%B8%80%E8%87%B4%EF%BC%9A%E5%AE%B9%E5%B7%AE%E6%9C%80%E7%B4%A7%22%5D%0A%20%20S2%20--%3E%20T2%5B%22%E6%9C%9F%E6%9C%9B%E5%90%8C%E5%88%86%E5%B8%83%EF%BC%9A%E7%BB%9F%E8%AE%A1%E5%AE%B9%E5%B7%AE%22%5D%0A%20%20S3%20--%3E%20T3%5B%22%E5%8F%AA%E6%B1%82%E6%8E%92%E5%BA%8F%E4%B8%80%E8%87%B4%EF%BC%9A%E5%AE%B9%E5%B7%AE%E6%9C%80%E6%9D%BE%22%5D%0A%20%20T1%20--%3E%20W%5B%22%E6%A1%A3%E4%BD%8D%E9%85%8D%E9%94%99%EF%BC%8C%E5%88%A4%E5%AE%9A%E5%A4%B1%E4%B9%89%22%5D%0A%20%20T2%20--%3E%20W%0A%20%20T3%20--%3E%20W%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">直觉类比：单步复算像让两位厨师用同一勺食材炒「同一秒」的菜，只比较这一锅——训练动力学和规模全部冻结，剩下的差异只能来自手艺（前向与反向的数值计算）本身。虽然最贵，但归因最干净。</span></p><p>赢了基线之后还有一问：效应量与种子方差的关系——差距小于噪声带，结论只能写「未观察到差异」，不能写「相当」或「持平」。「没赢」同样要写判因：基线欠账、预算不足、还是方法确实无效，三者进报告的档位不同。</p><p><span class="marginnote">Ferrari Dacrema 等 2019 复查推荐系统的 18 篇「突破」论文：仅 7 篇可复现，而这 7 篇里有 6 篇被调好的简单基线（如 TopPop）盖过。「赢的资格」不是 LLM 特有的洁癖，是所有基准学科的共同教训。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>对齐不是逼近到荒谬：为追 0.1 分烧掉归因预算，是把验收当成了目的——判定一到就停，余下的差异写进未排除项。基线校准也不做无限网格：重调空间要在报告里写明，空间大得离谱的「基线最好努力」本身不可信。基准分数的公信力有独立的一套问题（污染、判卷漂移），见<a href="/llm/eco-community-benchmark-credibility">社区基准的公信力</a>，本课只负责「对上与赢」的内部账。最后，对齐账与基线账是复现报告的核心两节，格式在产出单元展开；本课的纪律是：每个判定都能点回一个 run 与一份容差声明。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>「对上」四层锚点：端到端、曲线形态、逐层统计、单步复算；先粗后细，判定一到即停。</li><li>「赢」的资格：基线必须复刻官方、环境内重调、最好努力记档；校准费占预算约一成。</li><li>容差分档与坐标系绑定：逐位、同分布、排序一致，写错档位判定失义。</li><li>效应量小于种子噪声带时只能写「未观察到差异」。</li><li>出处：Ferrari Dacrema 等, 2019；Melis 等, 2018；Musgrave 等, 2020；数值口径见<a href="/llm/ti-numerical-health">数值健康检查</a>。</li></ul>',7))])}const _=n(d,[["render",p]]);export{f as __pageData,_ as default};
